interface ClientDoc {
  id: string
  projectId: string
  fileId: string | null
  category: string
  title: string
  documentNumber: string | null
  revision: string | null
  description: string | null
  receivedFrom: string | null
  transmissionDate: string | null
  status: string
  parentDocumentId: string | null
  uploadedByName: string | null
  downloadUrl: string | null
  previewUrl: string | null
  filename: string | null
  mimeType: string | null
  sizeBytes: number | null
  revisions: ClientDocRevision[]
  createdAt: string
}

// The query's nested `revisions` selection is deliberately smaller than the
// top-level doc (no projectId/parentDocumentId/uploadedById/mimeType/
// sizeBytes, and no revisions of its own) — a distinct, flatter shape.
interface ClientDocRevision {
  id: string
  fileId: string | null
  category: string
  title: string
  documentNumber: string | null
  revision: string | null
  description: string | null
  receivedFrom: string | null
  transmissionDate: string | null
  status: string
  uploadedByName: string | null
  downloadUrl: string | null
  previewUrl: string | null
  filename: string | null
  createdAt: string
}

function ClientDocumentsTab({
  projectId,
  theme,
  isAdmin,
}: {
  projectId: string
  theme: ReturnType<typeof useTheme>['theme']
  isAdmin?: boolean
}) {
  const { t } = useTranslation()
  const addToast = useToastStore((s) => s.addToast)
  const [filterCat, setFilterCat] = useState<CDCategory | 'all'>('all')
  const [search, setSearch] = useState('')
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [showModal, setShowModal] = useState(false)
  const [reviseDoc, setReviseDoc] = useState<ClientDoc | null>(null)
  const [editDoc, setEditDoc] = useState<ClientDoc | null>(null)
  const [uploading, setUploading] = useState(false)
  const [dropTarget, setDropTarget] = useState<'new' | 'revise' | null>(null)
  const [pendingFiles, setPendingFiles] = useState<{ fileId: string; filename: string }[]>([])
  const [form, setForm] = useState({
    title: '',
    documentNumber: '',
    revision: '',
    category: 'rfq_tender' as CDCategory,
    receivedFrom: '',
    transmissionDate: '',
    description: '',
  })
  const [revForm, setRevForm] = useState({
    revision: '',
    description: '',
    fileId: '',
    filename: '',
  })
  const [editForm, setEditForm] = useState({
    title: '',
    documentNumber: '',
    revision: '',
    category: 'rfq_tender' as CDCategory,
    receivedFrom: '',
    transmissionDate: '',
    description: '',
  })

  const { data, loading, refetch } = useQuery<ClientDocumentsQuery, ClientDocumentsQueryVariables>(CLIENT_DOCUMENTS_QUERY, {
    variables: { projectId },
    skip: !projectId,
    fetchPolicy: 'cache-and-network',
  })

  const [uploadDoc] = useMutation<UploadClientDocumentMutation, UploadClientDocumentMutationVariables>(UPLOAD_CLIENT_DOCUMENT)
  const [uploadRev] = useMutation<UploadClientDocumentRevisionMutation, UploadClientDocumentRevisionMutationVariables>(UPLOAD_CLIENT_DOCUMENT_REVISION)
  const [updateDoc] = useMutation<UpdateClientDocumentMutation, UpdateClientDocumentMutationVariables>(UPDATE_CLIENT_DOCUMENT)
  const [updateStatus] = useMutation<UpdateClientDocumentStatusMutation, UpdateClientDocumentStatusMutationVariables>(UPDATE_CLIENT_DOCUMENT_STATUS)
  const [deleteDoc] = useMutation<DeleteClientDocumentMutation, DeleteClientDocumentMutationVariables>(DELETE_CLIENT_DOCUMENT)

  const docs: ClientDoc[] = data?.clientDocuments ?? []

  const filtered = docs.filter((d) => {
    if (filterCat !== 'all' && d.category !== filterCat) return false
    if (search) {
      const q = search.toLowerCase()
      return (
        d.title.toLowerCase().includes(q) ||
        (d.documentNumber ?? '').toLowerCase().includes(q) ||
        (d.receivedFrom ?? '').toLowerCase().includes(q)
      )
    }
    return true
  })

  const uploadFile = async (file: File, onPicked: (fileId: string, filename: string) => void) => {
    setUploading(true)
    try {
      const { data: urlRes } = await api.post<{ fileId: string }>('/files/upload-url', {
        filename: file.name,
        mimeType: file.type || 'application/octet-stream',
        sizeBytes: file.size,
        category: 'attachment',
      })
      const { fileId } = urlRes
      const buf = await file.arrayBuffer()
      await api.post(`/files/${fileId}/content`, buf, {
        headers: { 'Content-Type': file.type || 'application/octet-stream' },
        timeout: 120_000,
      })
      onPicked(fileId, file.name)
    } catch {
      addToast({ type: 'error', message: t('proj.detail.fileUploadFailed') })
    } finally {
      setUploading(false)
    }
  }

  const pickFile = async (onPicked: (fileId: string, filename: string) => void) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '*/*'
    input.onchange = () => {
      const file = input.files?.[0]
      if (file) void uploadFile(file, onPicked)
    }
    input.click()
  }

  const dropFile = (
    e: React.DragEvent<HTMLDivElement>,
    onPicked: (fileId: string, filename: string) => void,
  ) => {
    e.preventDefault()
    setDropTarget(null)
    if (uploading) return
    const file = e.dataTransfer.files[0]
    if (file) void uploadFile(file, onPicked)
  }

  // Multi-file variants for the "New Document" upload zone — each file becomes
  // its own client document record (own auto-generated number, own title), so
  // uploads happen sequentially and each success is appended to pendingFiles
  // as it completes rather than waiting for the whole batch.
  const uploadFiles = async (files: File[]) => {
    for (const file of files) {
      await uploadFile(file, (fileId, filename) => {
        setPendingFiles((p) => [...p, { fileId, filename }])
      })
    }
  }

  const pickFiles = () => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '*/*'
    input.multiple = true
    input.onchange = () => {
      const files = Array.from(input.files ?? [])
      if (files.length > 0) void uploadFiles(files)
    }
    input.click()
  }

  const dropFiles = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    setDropTarget(null)
    if (uploading) return
    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) void uploadFiles(files)
  }

  const removePendingFile = (fileId: string) => {
    setPendingFiles((p) => p.filter((f) => f.fileId !== fileId))
  }

  const handleSubmit = async () => {
    if (!form.title || pendingFiles.length === 0) {
      addToast({ type: 'error', message: t('proj.detail.titleAndAtLeastOneFile') })
      return
    }
    // Multiple files become multiple document records (each with its own
    // auto-generated number) sharing the same category/received-from/etc. —
    // with more than one file, the title alone can't be reused verbatim for
    // each without colliding, so each gets the file's own name appended.
    const multi = pendingFiles.length > 1
    let failed = 0
    for (const f of pendingFiles) {
      const nameNoExt = f.filename.replace(/\.[^./\\]+$/, '')
      try {
        await uploadDoc({
          variables: {
            projectId,
            fileId: f.fileId,
            category: form.category,
            title: multi ? `${form.title} — ${nameNoExt}` : form.title,
            documentNumber: form.documentNumber || null,
            revision: form.revision || null,
            description: form.description || null,
            receivedFrom: form.receivedFrom || null,
            transmissionDate: form.transmissionDate || null,
          },
        })
      } catch (e: unknown) {
        failed++
        addToast({ type: 'error', message: `${f.filename}: ${(e as Error).message}` })
      }
    }
    const succeeded = pendingFiles.length - failed
    if (succeeded > 0) {
      addToast({
        type: failed > 0 ? 'warning' : 'success',
        message:
          succeeded === 1 && failed === 0
            ? t('proj.detail.documentUploaded')
            : failed > 0
              ? t('proj.detail.uploadedDocsFailed', { count: succeeded, failed })
              : t('proj.detail.uploadedDocs', { count: succeeded }),
      })
    }
    if (failed === 0) {
      setShowModal(false)
      setForm({
        title: '',
        documentNumber: '',
        revision: '',
        category: 'rfq_tender',
        receivedFrom: '',
        transmissionDate: '',
        description: '',
      })
      setPendingFiles([])
    }
    void refetch()
  }

  const handleRevise = async () => {
    if (!reviseDoc) return
    if (!revForm.revision || !revForm.fileId) {
      addToast({ type: 'error', message: t('proj.detail.revisionAndFileAreRequired') })
      return
    }
    try {
      await uploadRev({
        variables: {
          parentDocumentId: reviseDoc.id,
          fileId: revForm.fileId,
          revision: revForm.revision,
          description: revForm.description || null,
        },
      })
      addToast({ type: 'success', message: t('proj.detail.revisionUploaded') })
      setReviseDoc(null)
      setRevForm({ revision: '', description: '', fileId: '', filename: '' })
      void refetch()
    } catch (e: unknown) {
      addToast({ type: 'error', message: (e as Error).message })
    }
  }

  const handleArchive = async (doc: ClientDoc | ClientDocRevision) => {
    try {
      await updateStatus({
        variables: { id: doc.id, status: doc.status === 'archived' ? 'active' : 'archived' },
      })
      void refetch()
    } catch (e: unknown) {
      addToast({ type: 'error', message: (e as Error).message })
    }
  }

  const openEdit = (doc: ClientDoc) => {
    setEditDoc(doc)
    setEditForm({
      title: doc.title,
      documentNumber: doc.documentNumber ?? '',
      revision: doc.revision ?? '',
      category: doc.category as CDCategory,
      receivedFrom: doc.receivedFrom ?? '',
      transmissionDate: doc.transmissionDate ?? '',
      description: doc.description ?? '',
    })
  }

  const handleEditSave = async () => {
    if (!editDoc || !editForm.title) {
      addToast({ type: 'error', message: t('proj.detail.titleIsRequired') })
      return
    }
    try {
      await updateDoc({
        variables: {
          id: editDoc.id,
          title: editForm.title,
          category: editForm.category,
          documentNumber: editForm.documentNumber || null,
          revision: editForm.revision || null,
          description: editForm.description || null,
          receivedFrom: editForm.receivedFrom || null,
          transmissionDate: editForm.transmissionDate || null,
        },
      })
      addToast({ type: 'success', message: t('proj.detail.documentUpdated') })
      setEditDoc(null)
      void refetch()
    } catch (e: unknown) {
      addToast({ type: 'error', message: (e as Error).message })
    }
  }

  const handleDelete = async (doc: ClientDoc | ClientDocRevision) => {
    if (!window.confirm(t('proj.detail.delete3', { title: doc.title }))) return
    try {
      await deleteDoc({ variables: { id: doc.id } })
      void refetch()
    } catch (e: unknown) {
      addToast({ type: 'error', message: (e as Error).message })
    }
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  const fileTypeIcon = (filename: string | null) => {
    const ext = (filename?.split('.').pop() ?? '').toUpperCase()
    const MAP: Record<string, { bg: string; fg: string }> = {
      PDF: { bg: '#fee2e2', fg: '#b91c1c' },
      DOC: { bg: '#dbeafe', fg: '#1d4ed8' },
      DOCX: { bg: '#dbeafe', fg: '#1d4ed8' },
      XLS: { bg: '#d1fae5', fg: '#065f46' },
      XLSX: { bg: '#d1fae5', fg: '#065f46' },
      PPT: { bg: '#ffedd5', fg: '#9a3412' },
      PPTX: { bg: '#ffedd5', fg: '#9a3412' },
      PNG: { bg: '#ede9fe', fg: '#5b21b6' },
      JPG: { bg: '#ede9fe', fg: '#5b21b6' },
      JPEG: { bg: '#ede9fe', fg: '#5b21b6' },
      SVG: { bg: '#ede9fe', fg: '#5b21b6' },
      DWG: { bg: '#fef9c3', fg: '#a16207' },
      DXF: { bg: '#fef9c3', fg: '#a16207' },
      ZIP: { bg: '#f3f4f6', fg: '#374151' },
      RAR: { bg: '#f3f4f6', fg: '#374151' },
    }
    const c = MAP[ext] ?? { bg: '#e0f2fe', fg: '#0369a1' }
    const label = ext.slice(0, 4) || 'FILE'
    return (
      <div
        style={{
          width: 42,
          height: 42,
          borderRadius: 10,
          background: c.bg,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
          gap: 1,
        }}
      >
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" style={{ color: c.fg }}>
          <path
            d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6z"
            stroke={c.fg}
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <polyline
            points="14 2 14 8 20 8"
            stroke={c.fg}
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
        <span
          style={{
            fontSize: 7,
            fontWeight: 800,
            color: c.fg,
            letterSpacing: '0.03em',
            lineHeight: 1,
          }}
        >
          {label}
        </span>
      </div>
    )
  }

  const statusPill = (s: string) => {
    const cfg =
      s === 'active'
        ? { dot: '#22c55e', text: '#15803d', bg: '#f0fdf4', label: t('proj.detail.active') }
        : s === 'superseded'
          ? { dot: '#f59e0b', text: '#a16207', bg: '#fffbeb', label: t('proj.detail.superseded') }
          : { dot: '#9ca3af', text: '#6b7280', bg: '#f9fafb', label: t('proj.detail.archived') }
    return (
      <span
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 5,
          padding: '3px 10px',
          borderRadius: 999,
          background: cfg.bg,
          fontSize: 11,
          fontWeight: 600,
          color: cfg.text,
        }}
      >
        <span
          style={{ width: 6, height: 6, borderRadius: '50%', background: cfg.dot, flexShrink: 0 }}
        />
        {cfg.label}
      </span>
    )
  }

  const iconActionBtn = (
    tooltip: string,
    icon: React.ReactNode,
    onClick: () => void,
    variant: 'default' | 'danger' | 'accent' = 'default',
  ) => {
    const styles = {
      default: { color: theme.textMuted, hoverBg: theme.bgSurface },
      danger: { color: '#dc2626', hoverBg: '#fff1f2' },
      accent: { color: theme.accent, hoverBg: theme.accentBg },
    }[variant]
    return (
      <button
        title={tooltip}
        onClick={onClick}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: 30,
          height: 30,
          borderRadius: 6,
          border: `1px solid transparent`,
          background: 'transparent',
          color: styles.color,
          cursor: 'pointer',
          flexShrink: 0,
          transition: 'background 0.12s, border-color 0.12s',
        }}
        onMouseEnter={(e) => {
          const tx = e.currentTarget
          tx.style.background = styles.hoverBg
          tx.style.borderColor = variant === 'danger' ? '#fca5a5' : theme.border
        }}
        onMouseLeave={(e) => {
          const tx = e.currentTarget
          tx.style.background = 'transparent'
          tx.style.borderColor = 'transparent'
        }}
      >
        {icon}
      </button>
    )
  }

  const inp = (
    value: string,
    onChange: (v: string) => void,
    placeholder?: string,
    type = 'text',
  ) => (
    <input
      type={type}
      value={value}
      placeholder={placeholder}
      onChange={(e) => { onChange(e.target.value); }}
      style={{
        width: '100%',
        padding: '9px 12px',
        border: `1px solid ${theme.border}`,
        borderRadius: 8,
        background: theme.bgCanvas,
        color: theme.textPrimary,
        fontSize: 13,
        boxSizing: 'border-box',
        outline: 'none',
      }}
    />
  )
  const lbl = (tx: string, required = false) => (
    <div
      style={{
        fontSize: 11,
        fontWeight: 700,
        color: theme.textMuted,
        marginBottom: 5,
        textTransform: 'uppercase',
        letterSpacing: '0.05em',
      }}
    >
      {tx}
      {required && <span style={{ color: '#ef4444', marginInlineStart: 2 }}>*</span>}
    </div>
  )

  const COL = '52px minmax(0,1fr) 150px 72px 110px 180px'

  const renderDocRow = (doc: ClientDoc | ClientDocRevision, isRevision = false) => {
    const catColor = CD_COLORS[doc.category as CDCategory] ?? CD_COLORS.other
    const catLabel = CD_CATEGORIES.find((c) => c.key === doc.category)?.label ?? doc.category
    const isExpanded = expandedId === doc.id
    const hasRevisions = !isRevision && 'revisions' in doc && doc.revisions.length > 0
    const meta = [
      doc.receivedFrom && `From ${doc.receivedFrom}`,
      doc.transmissionDate && doc.transmissionDate,
      doc.uploadedByName && `by ${doc.uploadedByName}`,
      doc.documentNumber && `#${doc.documentNumber}`,
    ]
      .filter(Boolean)
      .join('  ·  ')

    return (
      <React.Fragment key={doc.id}>
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: COL,
            alignItems: 'center',
            padding: isRevision ? '10px 20px 10px 68px' : '14px 20px',
            borderBottom: `1px solid ${theme.border}`,
            background: isRevision
              ? theme.bgSurface + (theme.bgSurface.length === 7 ? '88' : '')
              : 'transparent',
            gap: 16,
          }}
        >
          {/* File icon */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            {hasRevisions && (
              <button
                onClick={() => { setExpandedId(isExpanded ? null : doc.id); }}
                style={{
                  all: 'unset',
                  cursor: 'pointer',
                  color: theme.textMuted,
                  fontSize: 10,
                  lineHeight: 1,
                  marginInlineEnd: -8,
                  position: 'relative',
                  zIndex: 1,
                  padding: '4px 2px',
                }}
              >
                <svg
                  width="12"
                  height="12"
                  viewBox="0 0 12 12"
                  fill="currentColor"
                  style={{
                    transition: 'transform 0.15s',
                    transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                  }}
                >
                  <path
                    d="M4 2l4 4-4 4"
                    stroke="currentColor"
                    strokeWidth="1.5"
                    fill="none"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
            )}
            {fileTypeIcon(doc.filename)}
          </div>

          {/* Title + meta */}
          <div style={{ minWidth: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
              {isRevision && (
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  style={{ color: theme.textMuted, flexShrink: 0 }}
                >
                  <path
                    d="M9 18l-6-6 6-6"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              )}
              <span
                style={{
                  fontWeight: 600,
                  fontSize: 13,
                  color: theme.textPrimary,
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                  maxWidth: '100%',
                }}
              >
                {doc.title}
              </span>
            </div>
            {meta && (
              <div
                style={{
                  fontSize: 11,
                  color: theme.textMuted,
                  marginTop: 3,
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {meta}
              </div>
            )}
            {doc.description && (
              <div
                style={{
                  fontSize: 11,
                  color: theme.textSecondary,
                  marginTop: 2,
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                  fontStyle: 'italic',
                }}
              >
                {doc.description}
              </div>
            )}
          </div>

          {/* Category */}
          <div>
            {!isRevision && (
              <span
                style={{
                  padding: '4px 10px',
                  borderRadius: 999,
                  background: catColor.bg,
                  color: catColor.text,
                  fontSize: 11,
                  fontWeight: 600,
                  whiteSpace: 'nowrap',
                }}
              >
                {catLabel}
              </span>
            )}
          </div>

          {/* Revision badge */}
          <div>
            {doc.revision ? (
              <span
                style={{
                  padding: '3px 9px',
                  borderRadius: 6,
                  background: theme.accentBg,
                  color: theme.accent,
                  fontSize: 11,
                  fontWeight: 700,
                }}
              >{t('proj.detail.rev2', { revision: doc.revision })}</span>
            ) : (
              <span style={{ color: theme.textMuted, fontSize: 12 }}>—</span>
            )}
          </div>

          {/* Status */}
          <div>{statusPill(doc.status)}</div>

          {/* Actions — icon-only compact row */}
          <div
            style={{ display: 'flex', gap: 2, alignItems: 'center', justifyContent: 'flex-end' }}
          >
            {/* Preview — works on archived documents too, deliberately not
                gated by doc.status; only whether a file exists. */}
            {(doc.previewUrl ?? doc.downloadUrl) &&
              iconActionBtn(
                t('proj.detail.preview'),
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" />
                </svg>,
                () => {
                  const url = doc.previewUrl ?? doc.downloadUrl
                  if (url) window.open(url, '_blank')
                },
              )}
            {/* Download */}
            {doc.downloadUrl &&
              iconActionBtn(
                t('proj.detail.download'),
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <polyline
                    points="7 10 12 15 17 10"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <line
                    x1="12"
                    y1="15"
                    x2="12"
                    y2="3"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                  />
                </svg>,
                () => {
                  if (doc.downloadUrl) window.open(doc.downloadUrl, '_blank')
                },
                'accent',
              )}
            {/* Divider */}
            {(isAdmin || !isRevision) && doc.downloadUrl && (
              <span
                style={{
                  width: 1,
                  height: 16,
                  background: theme.border,
                  margin: '0 4px',
                  flexShrink: 0,
                }}
              />
            )}
            {/* Edit */}
            {isAdmin &&
              !isRevision &&
              iconActionBtn(
                t('proj.detail.editDocument2'),
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>,
                () => { openEdit(doc as ClientDoc); },
              )}
            {/* + Revision */}
            {!isRevision &&
              iconActionBtn(
                t('proj.detail.uploadNewRevision'),
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M12 20h9"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <line x1="19" y1="7" x2="3" y2="23" stroke="none" />
                  <path d="M20 12v6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                  <path d="M17 15h6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>,
                () => {
                  setReviseDoc(doc as ClientDoc)
                  setRevForm({ revision: '', description: '', fileId: '', filename: '' })
                },
              )}
            {/* Archive / Restore */}
            {isAdmin &&
              iconActionBtn(
                doc.status === 'archived' ? t('proj.detail.restoreDocument') : t('proj.detail.archiveDocument'),
                doc.status === 'archived' ? (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                    <polyline
                      points="1 4 1 10 7 10"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                    <path
                      d="M3.51 15a9 9 0 1 0 .49-3.36"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                ) : (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                    <polyline
                      points="21 8 21 21 3 21 3 8"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                    <rect
                      x="1"
                      y="3"
                      width="22"
                      height="5"
                      rx="1"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                ),
                () => void handleArchive(doc),
              )}
            {/* Delete */}
            {isAdmin &&
              iconActionBtn(
                t('proj.detail.deleteDocument'),
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <polyline
                    points="3 6 5 6 21 6"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d="M19 6l-1 14H6L5 6"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d="M10 11v6M14 11v6"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>,
                () => void handleDelete(doc),
                'danger',
              )}
          </div>
        </div>
        {isExpanded && 'revisions' in doc && doc.revisions.map((rev) => renderDocRow(rev, true))}
      </React.Fragment>
    )
  }

  const openUpload = () => {
    setShowModal(true)
    setForm({
      title: '',
      documentNumber: '',
      revision: '',
      category: 'rfq_tender',
      receivedFrom: '',
      transmissionDate: '',
      description: '',
    })
    setPendingFiles([])
  }

  return (
    <div style={{ padding: '2px 0 20px' }}>
      {/* ── Toolbar ── */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          marginBottom: 16,
          flexWrap: 'wrap',
        }}
      >
        {/* Category pills */}
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', flex: 1 }}>
          {(['all', ...CD_CATEGORIES.map((c) => c.key)] as (CDCategory | 'all')[]).map((k) => {
            const label =
              k === 'all' ? t('proj.detail.allDocuments') : (CD_CATEGORIES.find((c) => c.key === k)?.label ?? k)
            const count = k === 'all' ? docs.length : docs.filter((d) => d.category === k).length
            const active = filterCat === k
            return (
              <button
                key={k}
                onClick={() => { setFilterCat(k); }}
                style={{
                  padding: '5px 13px',
                  borderRadius: 999,
                  fontSize: 12,
                  fontWeight: 500,
                  cursor: 'pointer',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                  transition: 'all 0.1s',
                  background: active ? theme.accent : 'transparent',
                  color: active ? '#fff' : theme.textSecondary,
                  border: active ? `1px solid ${theme.accent}` : `1px solid ${theme.border}`,
                }}
              >
                {label}
                {count > 0 && (
                  <span
                    style={{
                      padding: '0 5px',
                      borderRadius: 999,
                      background: active ? 'rgba(255,255,255,0.25)' : theme.bgSurface,
                      color: active ? '#fff' : theme.textMuted,
                      fontSize: 10,
                      fontWeight: 700,
                      lineHeight: '16px',
                      minWidth: 16,
                      textAlign: 'center',
                    }}
                  >
                    {count}
                  </span>
                )}
              </button>
            )
          })}
        </div>

        {/* Search */}
        <div style={{ position: 'relative' }}>
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            style={{
              position: 'absolute',
              insetInlineStart: 10,
              top: '50%',
              transform: 'translateY(-50%)',
              color: theme.textMuted,
              pointerEvents: 'none',
            }}
          >
            <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
            <line
              x1="21"
              y1="21"
              x2="16.65"
              y2="16.65"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>
          <input
            value={search}
            onChange={(e) => { setSearch(e.target.value); }}
            placeholder={t('proj.detail.searchDocuments')}
            style={{
              padding: '7px 12px 7px 32px',
              border: `1px solid ${theme.border}`,
              borderRadius: 8,
              background: theme.bgCanvas,
              color: theme.textPrimary,
              fontSize: 13,
              width: 210,
              outline: 'none',
            }}
          />
        </div>

        {/* Upload button */}
        <button
          onClick={openUpload}
          style={{
            padding: '7px 18px',
            borderRadius: 8,
            background: theme.accent,
            color: '#fff',
            border: 'none',
            fontSize: 13,
            fontWeight: 600,
            cursor: 'pointer',
            display: 'inline-flex',
            alignItems: 'center',
            gap: 7,
            whiteSpace: 'nowrap',
          }}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
            <line
              x1="12"
              y1="5"
              x2="12"
              y2="19"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
            />
            <line
              x1="5"
              y1="12"
              x2="19"
              y2="12"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
            />
          </svg>
          {t('proj.detail.uploadDocument')}
        </button>
      </div>

      {/* ── Document list ── */}
      {loading ? (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 12,
            padding: 60,
            color: theme.textMuted,
            fontSize: 14,
          }}
        >
          <svg
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            style={{ animation: 'spin 0.8s linear infinite' }}
          >
            <circle cx="12" cy="12" r="10" stroke={theme.border} strokeWidth="3" />
            <path
              d="M12 2a10 10 0 0 1 10 10"
              stroke={theme.accent}
              strokeWidth="3"
              strokeLinecap="round"
            />
          </svg>
          {t('proj.detail.loadingDocuments')}
        </div>
      ) : filtered.length === 0 ? (
        <div
          style={{
            border: `2px dashed ${theme.border}`,
            borderRadius: 16,
            padding: '64px 32px',
            textAlign: 'center',
          }}
        >
          <div
            style={{
              width: 64,
              height: 64,
              borderRadius: 16,
              background: theme.bgSurface,
              border: `1px solid ${theme.border}`,
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              marginBottom: 16,
            }}
          >
            <svg
              width="28"
              height="28"
              viewBox="0 0 24 24"
              fill="none"
              style={{ color: theme.textMuted }}
            >
              <path
                d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <div style={{ fontSize: 15, fontWeight: 600, color: theme.textPrimary, marginBottom: 6 }}>
            {search || filterCat !== 'all' ? t('proj.detail.noMatchingDocuments') : t('proj.detail.noDocumentsYet')}
          </div>
          <div
            style={{
              fontSize: 13,
              color: theme.textMuted,
              marginBottom: 24,
              maxWidth: 360,
              margin: '0 auto 24px',
            }}
          >
            {search || filterCat !== 'all'
              ? t('proj.detail.tryAdjustingYourSearchOrFilter')
              : t('proj.detail.uploadRfqPackagesDrawingsBoqSpecs')}
          </div>
          {!search && filterCat === 'all' && (
            <button
              onClick={openUpload}
              style={{
                padding: '8px 20px',
                borderRadius: 8,
                background: theme.accent,
                color: '#fff',
                border: 'none',
                fontSize: 13,
                fontWeight: 600,
                cursor: 'pointer',
              }}
            >
              {t('proj.detail.uploadFirstDocument')}
            </button>
          )}
        </div>
      ) : (
        <div style={{ border: `1px solid ${theme.border}`, borderRadius: 12, overflow: 'hidden' }}>
          {/* Column headers */}
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: COL,
              gap: 16,
              padding: '10px 20px',
              background: theme.bgSurface,
              borderBottom: `1px solid ${theme.border}`,
            }}
          >
            {['', t('proj.detail.document2'), t('proj.detail.category'), t('proj.detail.revision'), t('proj.detail.status'), t('proj.detail.actions')].map((h, i) => (
              <div
                key={i}
                style={{
                  fontSize: 10,
                  fontWeight: 700,
                  color: theme.textMuted,
                  textTransform: 'uppercase',
                  letterSpacing: '0.07em',
                  textAlign: i === 5 ? 'right' : 'left',
                }}
              >
                {h}
              </div>
            ))}
          </div>
          {/* Rows */}
          {filtered.map((doc) => renderDocRow(doc, false))}
        </div>
      )}

      {/* ── Upload Modal ── */}
      {showModal && (
        <Modal
          open={true}
          size="lg"
          title={t('proj.detail.uploadClientDocument')}
          onClose={() => {
            setShowModal(false)
            setPendingFiles([])
          }}
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div
              style={{
                padding: '8px 12px',
                background: theme.accentBg,
                border: `1px solid ${theme.accentBorder}`,
                borderRadius: 7,
                fontSize: 12,
                color: theme.textMuted,
              }}
            >
              {t('proj.detail.documentNumberIsAutoGeneratedOn')}
            </div>
            <div>
              {lbl(t('proj.detail.documentTitle'), true)}
              {inp(
                form.title,
                (v) => { setForm((f) => ({ ...f, title: v })); },
                t('proj.detail.eGRfqPackageCivilWorks'),
              )}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <div>
                {lbl(t('proj.detail.category'))}
                <select
                  value={form.category}
                  onChange={(e) =>
                    { setForm((f) => ({ ...f, category: e.target.value as CDCategory })); }
                  }
                  style={{
                    width: '100%',
                    padding: '9px 12px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: 8,
                    background: theme.bgCanvas,
                    color: theme.textPrimary,
                    fontSize: 13,
                  }}
                >
                  {CD_CATEGORIES.map((c) => (
                    <option key={c.key} value={c.key}>
                      {c.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                {lbl(t('proj.detail.revision'))}
                {inp(
                  form.revision,
                  (v) => { setForm((f) => ({ ...f, revision: v })); },
                  'e.g. A, 1, B2',
                )}
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <div>
                {lbl(t('proj.detail.transmissionDate'))}
                {inp(
                  form.transmissionDate,
                  (v) => { setForm((f) => ({ ...f, transmissionDate: v })); },
                  '',
                  'date',
                )}
              </div>
              <div>
                {lbl(t('proj.detail.receivedFrom'))}
                {inp(
                  form.receivedFrom,
                  (v) => { setForm((f) => ({ ...f, receivedFrom: v })); },
                  t('proj.detail.clientNameOrOrganisation'),
                )}
              </div>
            </div>

            <div>
              {lbl(t('proj.detail.notes2'))}
              <textarea
                value={form.description}
                onChange={(e) => { setForm((f) => ({ ...f, description: e.target.value })); }}
                placeholder={t('proj.detail.optionalContextOrNotesAboutThis')}
                style={{
                  width: '100%',
                  padding: '9px 12px',
                  border: `1px solid ${theme.border}`,
                  borderRadius: 8,
                  background: theme.bgCanvas,
                  color: theme.textPrimary,
                  fontSize: 13,
                  minHeight: 72,
                  resize: 'vertical',
                  boxSizing: 'border-box',
                  outline: 'none',
                }}
              />
            </div>

            {/* File picker zone — multiple files allowed; each becomes its own
                document record sharing this form's category/received-from/etc. */}
            <div>
              {lbl(t('proj.detail.files'), true)}
              {pendingFiles.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 10 }}>
                  {pendingFiles.map((f) => (
                    <div
                      key={f.fileId}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        padding: '6px 10px',
                        border: `1px solid ${theme.border}`,
                        borderRadius: 7,
                        fontSize: 12,
                        color: theme.textSecondary,
                      }}
                    >
                      <span
                        style={{
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap',
                          flex: 1,
                        }}
                      >
                        ✓ {f.filename}
                      </span>
                      <button
                        onClick={() => {
                          removePendingFile(f.fileId)
                        }}
                        style={{
                          border: 'none',
                          background: 'none',
                          color: '#ef4444',
                          cursor: 'pointer',
                          fontSize: 12,
                          fontWeight: 600,
                          flexShrink: 0,
                          marginInlineStart: 8,
                        }}
                      >
                        {t('proj.detail.remove2')}
                      </button>
                    </div>
                  ))}
                </div>
              )}
              <div
                onClick={() => {
                  if (!uploading) pickFiles()
                }}
                onDragOver={(e) => {
                  e.preventDefault()
                  if (!uploading) setDropTarget('new')
                }}
                onDragLeave={() => { setDropTarget(null); }}
                onDrop={dropFiles}
                style={{
                  border: `2px dashed ${dropTarget === 'new' ? theme.accent : theme.border}`,
                  borderRadius: 10,
                  padding: '20px 16px',
                  textAlign: 'center',
                  cursor: uploading ? 'not-allowed' : 'pointer',
                  background: dropTarget === 'new' ? theme.accentBg : 'transparent',
                  transition: 'all 0.15s',
                }}
              >
                {uploading ? (
                  <div style={{ color: theme.textMuted, fontSize: 13 }}>{t('proj.detail.uploading')}</div>
                ) : (
                  <div>
                    <svg
                      width="24"
                      height="24"
                      viewBox="0 0 24 24"
                      fill="none"
                      style={{ color: theme.textMuted, margin: '0 auto 6px' }}
                    >
                      <path
                        d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                      <polyline
                        points="17 8 12 3 7 8"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                      <line
                        x1="12"
                        y1="3"
                        x2="12"
                        y2="15"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                      />
                    </svg>
                    <div style={{ fontSize: 13, fontWeight: 500, color: theme.textSecondary }}>
                      {pendingFiles.length > 0 ? t('proj.detail.clickToAddMoreFiles') : t('proj.detail.clickToSelectFiles')}
                    </div>
                    <div style={{ fontSize: 11, color: theme.textMuted, marginTop: 3 }}>
                      {t('proj.detail.pdfDwgXlsxDocxImagesAny')}
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div
              style={{
                display: 'flex',
                justifyContent: 'flex-end',
                gap: 10,
                paddingTop: 4,
                borderTop: `1px solid ${theme.border}`,
                marginTop: 4,
              }}
            >
              <button
                onClick={() => {
                  setShowModal(false)
                  setPendingFiles([])
                }}
                style={{
                  padding: '8px 18px',
                  borderRadius: 8,
                  background: 'transparent',
                  border: `1px solid ${theme.border}`,
                  color: theme.textSecondary,
                  fontSize: 13,
                  cursor: 'pointer',
                }}
              >
                {t('proj.detail.cancel')}
              </button>
              <button
                disabled={!form.title || pendingFiles.length === 0 || uploading}
                onClick={() => void handleSubmit()}
                style={{
                  padding: '8px 22px',
                  borderRadius: 8,
                  background:
                    form.title && pendingFiles.length > 0 && !uploading
                      ? theme.accent
                      : theme.border,
                  color: '#fff',
                  border: 'none',
                  fontSize: 13,
                  fontWeight: 600,
                  cursor:
                    form.title && pendingFiles.length > 0 && !uploading ? 'pointer' : 'not-allowed',
                }}
              >
                {t('proj.detail.uploadDocument')}
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* ── Revision Modal ── */}
      {reviseDoc && (
        <Modal
          open={true}
          title={t('proj.detail.newRevision', { title: reviseDoc.title })}
          onClose={() => { setReviseDoc(null); }}
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div
              style={{
                padding: '10px 14px',
                borderRadius: 8,
                background: theme.bgSurface,
                border: `1px solid ${theme.border}`,
                fontSize: 12,
                color: theme.textSecondary,
              }}
            >
              {t('proj.detail.currentVersion')}{' '}
              <strong style={{ color: theme.textPrimary }}>{t('proj.detail.rev3', { value: reviseDoc.revision ?? 'Initial' })}</strong>
              {reviseDoc.status !== 'archived' && (
                <span style={{ marginInlineStart: 8, color: '#a16207' }}>{t('proj.detail.willBeMarkedSuperseded')}</span>
              )}
            </div>

            <div>
              {lbl(t('proj.detail.newRevisionNumber'), true)}
              {inp(
                revForm.revision,
                (v) => { setRevForm((f) => ({ ...f, revision: v })); },
                'e.g. B, 2, C1',
              )}
            </div>

            <div>
              {lbl(t('proj.detail.changeSummary2'))}
              <textarea
                value={revForm.description}
                onChange={(e) => { setRevForm((f) => ({ ...f, description: e.target.value })); }}
                placeholder={t('proj.detail.whatChangedInThisRevision')}
                style={{
                  width: '100%',
                  padding: '9px 12px',
                  border: `1px solid ${theme.border}`,
                  borderRadius: 8,
                  background: theme.bgCanvas,
                  color: theme.textPrimary,
                  fontSize: 13,
                  minHeight: 72,
                  resize: 'vertical',
                  boxSizing: 'border-box',
                  outline: 'none',
                }}
              />
            </div>

            <div>
              {lbl(t('proj.detail.revisedFile'), true)}
              <div
                onClick={() =>
                  void (
                    !uploading &&
                    pickFile((fid, fn) => { setRevForm((f) => ({ ...f, fileId: fid, filename: fn })); })
                  )
                }
                onDragOver={(e) => {
                  e.preventDefault()
                  if (!uploading) setDropTarget('revise')
                }}
                onDragLeave={() => { setDropTarget(null); }}
                onDrop={(e) =>
                  { dropFile(e, (fid, fn) => { setRevForm((f) => ({ ...f, fileId: fid, filename: fn })); }); }
                }
                style={{
                  border: `2px dashed ${dropTarget === 'revise' ? theme.accent : revForm.fileId ? theme.accent : theme.border}`,
                  borderRadius: 10,
                  padding: '20px 16px',
                  textAlign: 'center',
                  cursor: uploading ? 'not-allowed' : 'pointer',
                  background:
                    dropTarget === 'revise'
                      ? theme.accentBg
                      : revForm.fileId
                        ? theme.accentBg
                        : 'transparent',
                }}
              >
                {uploading ? (
                  <div style={{ color: theme.textMuted, fontSize: 13 }}>{t('proj.detail.uploading')}</div>
                ) : revForm.fileId ? (
                  <div>
                    <div style={{ fontSize: 18, marginBottom: 4 }}>✓</div>
                    <div style={{ fontSize: 13, fontWeight: 600, color: theme.accent }}>
                      {revForm.filename}
                    </div>
                    <div style={{ fontSize: 11, color: theme.textMuted, marginTop: 2 }}>
                      {t('proj.detail.clickToReplace')}
                    </div>
                  </div>
                ) : (
                  <div style={{ fontSize: 13, color: theme.textSecondary }}>
                    {t('proj.detail.clickToSelectRevisedFile')}
                  </div>
                )}
              </div>
            </div>

            <div
              style={{
                display: 'flex',
                justifyContent: 'flex-end',
                gap: 10,
                paddingTop: 4,
                borderTop: `1px solid ${theme.border}`,
                marginTop: 4,
              }}
            >
              <button
                onClick={() => { setReviseDoc(null); }}
                style={{
                  padding: '8px 18px',
                  borderRadius: 8,
                  background: 'transparent',
                  border: `1px solid ${theme.border}`,
                  color: theme.textSecondary,
                  fontSize: 13,
                  cursor: 'pointer',
                }}
              >
                {t('proj.detail.cancel')}
              </button>
              <button
                disabled={!revForm.revision || !revForm.fileId || uploading}
                onClick={() => void handleRevise()}
                style={{
                  padding: '8px 22px',
                  borderRadius: 8,
                  background:
                    revForm.revision && revForm.fileId && !uploading ? theme.accent : theme.border,
                  color: '#fff',
                  border: 'none',
                  fontSize: 13,
                  fontWeight: 600,
                  cursor:
                    revForm.revision && revForm.fileId && !uploading ? 'pointer' : 'not-allowed',
                }}
              >
                {t('proj.detail.uploadRevision')}
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* ── Edit Modal ── */}
      {editDoc && (
        <Modal
          open={true}
          title={t('proj.detail.editDocument', { title: editDoc.title })}
          onClose={() => { setEditDoc(null); }}
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <div style={{ gridColumn: '1 / -1' }}>
                {lbl(t('proj.detail.title'), true)}
                {inp(
                  editForm.title,
                  (v) => { setEditForm((f) => ({ ...f, title: v })); },
                  t('proj.detail.documentTitle2'),
                )}
              </div>
              <div>
                {lbl(t('proj.detail.category'), true)}
                <select
                  value={editForm.category}
                  onChange={(e) =>
                    { setEditForm((f) => ({ ...f, category: e.target.value as CDCategory })); }
                  }
                  style={{
                    width: '100%',
                    padding: '9px 12px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: 8,
                    background: theme.bgCanvas,
                    color: theme.textPrimary,
                    fontSize: 13,
                    boxSizing: 'border-box' as const,
                    outline: 'none',
                  }}
                >
                  {CD_CATEGORIES.map((c) => (
                    <option key={c.key} value={c.key}>
                      {c.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                {lbl(t('proj.detail.revision'))}
                {inp(
                  editForm.revision,
                  (v) => { setEditForm((f) => ({ ...f, revision: v })); },
                  'e.g. A, 1, C2',
                )}
              </div>
              <div>
                {lbl(t('proj.detail.documentNumber'))}
                {inp(
                  editForm.documentNumber,
                  (v) => { setEditForm((f) => ({ ...f, documentNumber: v })); },
                  t('proj.detail.eGDoc001'),
                )}
              </div>
              <div>
                {lbl(t('proj.detail.receivedFrom'))}
                {inp(
                  editForm.receivedFrom,
                  (v) => { setEditForm((f) => ({ ...f, receivedFrom: v })); },
                  t('proj.detail.clientSenderName'),
                )}
              </div>
              <div>
                {lbl(t('proj.detail.transmissionDate'))}
                {inp(
                  editForm.transmissionDate,
                  (v) => { setEditForm((f) => ({ ...f, transmissionDate: v })); },
                  '',
                  'date',
                )}
              </div>
              <div style={{ gridColumn: '1 / -1' }}>
                {lbl(t('proj.detail.description'))}
                <textarea
                  value={editForm.description}
                  onChange={(e) => { setEditForm((f) => ({ ...f, description: e.target.value })); }}
                  placeholder={t('proj.detail.briefDescription')}
                  style={{
                    width: '100%',
                    padding: '9px 12px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: 8,
                    background: theme.bgCanvas,
                    color: theme.textPrimary,
                    fontSize: 13,
                    minHeight: 72,
                    resize: 'vertical',
                    boxSizing: 'border-box',
                    outline: 'none',
                  }}
                />
              </div>
            </div>
            <div
              style={{
                display: 'flex',
                justifyContent: 'flex-end',
                gap: 10,
                paddingTop: 4,
                borderTop: `1px solid ${theme.border}`,
                marginTop: 4,
              }}
            >
              <button
                onClick={() => { setEditDoc(null); }}
                style={{
                  padding: '8px 18px',
                  borderRadius: 8,
                  background: 'transparent',
                  border: `1px solid ${theme.border}`,
                  color: theme.textSecondary,
                  fontSize: 13,
                  cursor: 'pointer',
                }}
              >
                {t('proj.detail.cancel')}
              </button>
              <button
                disabled={!editForm.title}
                onClick={() => void handleEditSave()}
                style={{
                  padding: '8px 22px',
                  borderRadius: 8,
                  background: editForm.title ? theme.accent : theme.border,
                  color: '#fff',
                  border: 'none',
                  fontSize: 13,
                  fontWeight: 600,
                  cursor: editForm.title ? 'pointer' : 'not-allowed',
                }}
              >
                {t('proj.detail.saveChanges')}
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  )
}

// ── Bidding types ──────────────────────────────────────────────────────────
interface BidDeliverable {
  id: string
  projectId: string
  name: string
  deliverableType: string
  discipline: string | null
  status: string
  assignedTo: string | null
  dueDate: string | null
  notes: string | null
  sequence: number
  createdByName: string | null
  fileCount: number
  files: {
    id: string
    fileId: string
    filename: string
    mimeType: string
    sizeBytes: number | null
    title: string | null
    description: string | null
    createdAt: string
    downloadUrl: string | null
  }[]
  createdAt: string
  updatedAt: string
}
interface BidCostItem {
  id: string
  costType: string
  description: string
  quantity: number | null
  unit: string | null
  unitCost: number | null
  totalCost: number | null
  currencyCode: string
  supplierRef: string | null
  notes: string | null
  sequence: number
}
interface BidQuotation {
  id: string
  supplierName: string
  itemDescription: string
  amount: number | null
  currencyCode: string
  validityDate: string | null
  downloadUrl: string | null
  filename: string | null
  notes: string | null
  status: string
  createdAt: string
}
