interface UploadState {
  uploading: boolean
  progress: number
}

async function execUpload(
  file: File,
  entityId: string,
  entityType: string,
  onUpload: (v: Record<string, unknown>) => void,
  setState: React.Dispatch<React.SetStateAction<UploadState>>,
) {
  const ENTITY_ID_KEY: Record<string, string> = {
    rfi: 'rfiId',
    site_instruction: 'siId',
    inspection_request: 'irId',
    ncr: 'ncrId',
    hse_record: 'hseId',
    tq: 'tqId',
    daily_report: 'reportId',
  }
  setState({ uploading: true, progress: 0 })
  try {
    const { data: urlRes } = await api.post<{ fileId: string }>('/files/upload-url', {
      filename: file.name,
      mimeType: file.type,
      sizeBytes: file.size,
      category: 'attachment',
    })
    const { fileId } = urlRes
    setState({ uploading: true, progress: 30 })
    const buf = await file.arrayBuffer()
    await api.post(`/files/${fileId}/content`, buf, {
      headers: { 'Content-Type': file.type },
      timeout: 120_000,
    })
    setState({ uploading: true, progress: 90 })
    const idKey = ENTITY_ID_KEY[entityType] ?? 'entityId'
    onUpload({ [idKey]: entityId, fileId, title: file.name })
  } finally {
    setState({ uploading: false, progress: 0 })
  }
}

function ExecUploadButton({
  entityId,
  entityType,
  onUpload,
  th,
}: {
  entityId: string
  entityType: string
  onUpload: (v: Record<string, unknown>) => void
  th: Record<string, string>
}) {
  const { t } = useTranslation()
  const [state, setState] = React.useState<UploadState>({ uploading: false, progress: 0 })
  const ref = React.useRef<HTMLInputElement>(null)
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center' }}>
      <input
        ref={ref}
        type="file"
        style={{ display: 'none' }}
        onChange={(e) => {
          const f = e.target.files?.[0]
          if (f) void execUpload(f, entityId, entityType, onUpload, setState)
          e.target.value = ''
        }}
      />
      <button
        onClick={() => ref.current?.click()}
        disabled={state.uploading}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: '5px',
          padding: '5px 12px',
          borderRadius: '6px',
          border: `1px solid ${th.border}`,
          background: 'none',
          color: th.textSecondary,
          fontSize: '12px',
          fontWeight: 500,
          cursor: state.uploading ? 'not-allowed' : 'pointer',
          opacity: state.uploading ? 0.7 : 1,
        }}
      >
        {state.uploading ? (
          <>{t('proj.detail.uploading2', { progress: state.progress })}</>
        ) : (
          <>
            <svg
              width="12"
              height="12"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
            </svg>
            {t('proj.detail.attachFile')}
          </>
        )}
      </button>
    </span>
  )
}

