  // Generic add/remove row-table editor shared by every repeating-row
  // section of the Daily Report form (progress metrics, safety stats,
  // engineering/procurement/construction rows, manpower, equipment, risks,
  // client actions…) — one editor covers all of them instead of a bespoke
  // component per section.
  type RowCol = {
    key: string
    label: string
    type?: 'text' | 'number' | 'date'
    options?: string[]
  }
  const smallCellStyle: React.CSSProperties = {
    padding: '6px 8px',
    borderRadius: '5px',
    border: `1px solid ${th.border}`,
    background: th.bgCanvas,
    color: th.textPrimary,
    fontSize: '12px',
    width: '100%',
    boxSizing: 'border-box',
  }
  const rowsEditor = (
    rows: Record<string, string>[],
    setRows: (rows: Record<string, string>[]) => void,
    columns: RowCol[],
    opts?: { allowAddRemove?: boolean; addLabel?: string },
  ) => {
    const allowAddRemove = opts?.allowAddRemove ?? true
    const gridCols = `${columns.map(() => '1fr').join(' ')}${allowAddRemove ? ' 28px' : ''}`
    return (
      <div style={{ overflowX: 'auto', marginBottom: '12px' }}>
        <div style={{ minWidth: `${columns.length * 130}px` }}>
          <div style={{ display: 'grid', gridTemplateColumns: gridCols, gap: '6px', marginBottom: '6px' }}>
            {columns.map((c) => (
              <span
                key={c.key}
                style={{
                  fontSize: '10px',
                  fontWeight: 700,
                  color: th.textMuted,
                  textTransform: 'uppercase',
                  letterSpacing: '0.04em',
                }}
              >
                {c.label}
              </span>
            ))}
            {allowAddRemove && <span />}
          </div>
          {rows.map((row, idx) => (
            <div
              key={idx}
              style={{
                display: 'grid',
                gridTemplateColumns: gridCols,
                gap: '6px',
                marginBottom: '6px',
                alignItems: 'center',
              }}
            >
              {columns.map((c) =>
                c.options ? (
                  <select
                    key={c.key}
                    value={row[c.key] ?? ''}
                    onChange={(e) => {
                      const next = [...rows]
                      next[idx] = { ...next[idx], [c.key]: e.target.value }
                      setRows(next)
                    }}
                    style={smallCellStyle}
                  >
                    <option value="">—</option>
                    {c.options.map((o) => (
                      <option key={o} value={o}>
                        {o.replace(/_/g, ' ')}
                      </option>
                    ))}
                  </select>
                ) : (
                  <input
                    key={c.key}
                    type={c.type ?? 'text'}
                    value={row[c.key] ?? ''}
                    onChange={(e) => {
                      const next = [...rows]
                      next[idx] = { ...next[idx], [c.key]: e.target.value }
                      setRows(next)
                    }}
                    style={smallCellStyle}
                  />
                ),
              )}
              {allowAddRemove && (
                <button
                  onClick={() => { setRows(rows.filter((_, i) => i !== idx)); }}
                  style={{
                    padding: '4px 6px',
                    border: 'none',
                    background: '#fef2f2',
                    color: '#991b1b',
                    borderRadius: '5px',
                    fontSize: '12px',
                    cursor: 'pointer',
                  }}
                >
                  ✕
                </button>
              )}
            </div>
          ))}
          {allowAddRemove && (
            <button
              onClick={() => {
                setRows([...rows, Object.fromEntries(columns.map((c) => [c.key, '']))])
              }}
              style={{
                marginTop: '4px',
                padding: '5px 12px',
                borderRadius: '6px',
                border: `1px dashed ${th.border}`,
                background: 'transparent',
                color: th.textSecondary,
                fontSize: '12px',
                cursor: 'pointer',
                width: '100%',
              }}
            >
              {opts?.addLabel ?? t('proj.detail.addRow')}
            </button>
          )}
        </div>
      </div>
    )
  }

  const checkboxGroup = (
    options: string[],
    selected: string[],
    onChange: (next: string[]) => void,
  ) => (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '14px', marginBottom: '12px' }}>
      {options.map((o) => (
        <label
          key={o}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            fontSize: '13px',
            color: th.textPrimary,
            cursor: 'pointer',
          }}
        >
          <input
            type="checkbox"
            checked={selected.includes(o)}
            onChange={(e) => {
              onChange(e.target.checked ? [...selected, o] : selected.filter((x) => x !== o))
            }}
          />
          {o.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())}
        </label>
      ))}
    </div>
  )

  const sectionTitle = (label: string) => (
    <h4
      style={{
        margin: '20px 0 10px',
        fontSize: '12px',
        fontWeight: 700,
        color: th.textMuted,
        textTransform: 'uppercase',
        letterSpacing: '0.06em',
        borderTop: `1px solid ${th.border}`,
        paddingTop: '16px',
      }}
    >
      {label}
    </h4>
  )

  // ── RFIs section ──────────────────────────────────────────────────────────
  function openRfiCreate() {
    const nextNum = String(rfis.length + 1).padStart(3, '0')
    setRfiForm({
      rfiNumber: nextNum,
      subject: '',
      description: '',
      drawingRef: '',
      specRef: '',
      raisedByName: currentUserName,
      raisedDate: new Date().toISOString().slice(0, 10),
      requiredDate: '',
      response: '',
      respondedByName: '',
      respondedDate: '',
      status: 'open',
    })
    setRfiModal({ open: true, row: null, mode: 'create' })
  }
  function openRfiEdit(r: RFIRow) {
    setRfiForm({
      rfiNumber: r.rfiNumber,
      subject: r.subject,
      description: r.description ?? '',
      drawingRef: r.drawingRef ?? '',
      specRef: r.specRef ?? '',
      raisedByName: r.raisedByName ?? '',
      raisedDate: r.raisedDate,
      requiredDate: r.requiredDate ?? '',
      response: r.response ?? '',
      respondedByName: r.respondedByName ?? '',
      respondedDate: r.respondedDate ?? '',
      status: r.status,
    })
    setRfiModal({ open: true, row: r, mode: 'edit' })
  }
  function openRfiRespond(r: RFIRow) {
    setRfiForm((f) => ({
      ...f,
      response: r.response ?? '',
      respondedByName: currentUserName,
      respondedDate: r.respondedDate ?? new Date().toISOString().slice(0, 10),
    }))
    setRfiModal({ open: true, row: r, mode: 'respond' })
  }
  function saveRfi() {
    const v = { ...rfiForm }
    if (rfiModal.mode === 'create') {
      onCreateRFI({ projectId, ...v })
    } else if (rfiModal.mode === 'edit' && rfiModal.row) {
      onUpdateRFI({ id: rfiModal.row.id, ...v })
    } else if (rfiModal.mode === 'respond' && rfiModal.row) {
      onRespondRFI({
        id: rfiModal.row.id,
        response: rfiForm.response,
        respondedByName: rfiForm.respondedByName,
        respondedDate: rfiForm.respondedDate,
      })
    }
    setRfiModal({ open: false, row: null, mode: 'create' })
  }

